create type public.management_review_status as enum ('SCHEDULED','IN_PROGRESS','COMPLETED');
create sequence public.management_review_number_sequence start 1;
create or replace function public.next_management_review_number() returns text language plpgsql volatile set search_path=public as $$ begin return format('MGR-%s-%s',to_char(current_date,'YYYY'),lpad(nextval('public.management_review_number_sequence')::text,6,'0')); end; $$;
create table public.management_reviews(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,review_number text not null unique default public.next_management_review_number(),scheduled_at timestamptz not null,agenda text not null check(length(trim(agenda)) between 10 and 10000),status public.management_review_status not null default 'SCHEDULED',conclusion text,created_by uuid not null references public.user_profiles(id) on delete restrict,completed_by uuid references public.user_profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz,check(conclusion is null or length(trim(conclusion)) between 10 and 10000)
);
create table public.management_review_decisions(
 id uuid primary key default gen_random_uuid(),review_id uuid not null references public.management_reviews(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,title text not null check(length(trim(title)) between 5 and 240),decision text not null check(length(trim(decision)) between 10 and 10000),due_at timestamptz,created_by uuid not null references public.user_profiles(id) on delete restrict,created_at timestamptz not null default now()
);
create index management_reviews_org_status_idx on public.management_reviews(organization_id,status,scheduled_at); create index management_review_decisions_review_idx on public.management_review_decisions(review_id,created_at);
create trigger management_reviews_updated before update on public.management_reviews for each row execute function public.set_updated_at();
alter table public.management_reviews enable row level security; alter table public.management_review_decisions enable row level security;
create policy "governance reads management reviews" on public.management_reviews for select to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','AUDITOR']::public.platform_role[]));
create policy "governance reads management review decisions" on public.management_review_decisions for select to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','AUDITOR']::public.platform_role[]));
create or replace function public.create_management_review(target_organization_id uuid,target_scheduled_at timestamptz,target_agenda text)
returns uuid language plpgsql security definer set search_path=public as $$ declare review_id uuid;
begin if not public.has_organization_role(target_organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'MANAGEMENT_REVIEW_NOT_AUTHORIZED'; end if; if target_scheduled_at is null or coalesce(length(trim(target_agenda)),0) not between 10 and 10000 then raise exception 'MANAGEMENT_REVIEW_INVALID_INPUT'; end if;
insert into public.management_reviews(organization_id,scheduled_at,agenda,created_by) values(target_organization_id,target_scheduled_at,trim(target_agenda),auth.uid()) returning id into review_id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(target_organization_id,auth.uid(),'MANAGEMENT_REVIEW_CREATED','management_review',review_id,jsonb_build_object('scheduled_at',target_scheduled_at),'WEB'); return review_id; end; $$;
create or replace function public.add_management_review_decision(target_review_id uuid,target_title text,target_decision text,target_due_at timestamptz default null)
returns uuid language plpgsql security definer set search_path=public as $$ declare review public.management_reviews%rowtype; decision_id uuid;
begin select * into review from public.management_reviews where id=target_review_id for update; if review.id is null or not public.has_organization_role(review.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'MANAGEMENT_REVIEW_NOT_AUTHORIZED'; end if; if review.status='COMPLETED' then raise exception 'MANAGEMENT_REVIEW_COMPLETED'; end if; if coalesce(length(trim(target_title)),0) not between 5 and 240 or coalesce(length(trim(target_decision)),0) not between 10 and 10000 then raise exception 'MANAGEMENT_REVIEW_DECISION_INVALID'; end if;
insert into public.management_review_decisions(review_id,organization_id,title,decision,due_at,created_by) values(review.id,review.organization_id,trim(target_title),trim(target_decision),target_due_at,auth.uid()) returning id into decision_id; update public.management_reviews set status='IN_PROGRESS' where id=review.id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(review.organization_id,auth.uid(),'MANAGEMENT_REVIEW_DECISION_ADDED','management_review_decision',decision_id,jsonb_build_object('review_id',review.id),'WEB'); return decision_id; end; $$;
create or replace function public.complete_management_review(target_review_id uuid,target_conclusion text)
returns void language plpgsql security definer set search_path=public as $$ declare review public.management_reviews%rowtype;
begin select * into review from public.management_reviews where id=target_review_id for update; if review.id is null or not public.has_organization_role(review.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'MANAGEMENT_REVIEW_NOT_AUTHORIZED'; end if; if review.status='COMPLETED' then raise exception 'MANAGEMENT_REVIEW_ALREADY_COMPLETED'; end if; if coalesce(length(trim(target_conclusion)),0) not between 10 and 10000 then raise exception 'MANAGEMENT_REVIEW_CONCLUSION_REQUIRED'; end if;
update public.management_reviews set status='COMPLETED',conclusion=trim(target_conclusion),completed_at=clock_timestamp(),completed_by=auth.uid() where id=review.id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(review.organization_id,auth.uid(),'MANAGEMENT_REVIEW_COMPLETED','management_review',review.id,jsonb_build_object('status','COMPLETED'),'WEB'); end; $$;
revoke all on function public.create_management_review(uuid,timestamptz,text) from public; revoke all on function public.add_management_review_decision(uuid,text,text,timestamptz) from public; revoke all on function public.complete_management_review(uuid,text) from public;
grant execute on function public.create_management_review(uuid,timestamptz,text) to authenticated; grant execute on function public.add_management_review_decision(uuid,text,text,timestamptz) to authenticated; grant execute on function public.complete_management_review(uuid,text) to authenticated;
